"""Interface definitions."""

import abc
import typing

from jsilib import _utils
from jsilib.aio.interface import IClosable

from .frames import Frame

__all__ = export = _utils.ExportList()


@export
class ITransportConnection(IClosable):
    """Represents transport layer connection between two peers.

    Allows peers to exchange JSI frames and ensures that each frame is sent as
    a whole, with no interleaving with other frames.
    """

    @abc.abstractmethod
    async def recv(self) -> Frame:
        """Await for a next frame from the remote peer."""

    @abc.abstractmethod
    def send_nowait(self, frame: Frame):
        """Send frame to the remote peer without blocking.

        Unlike :meth:`send`, this method simply adds *frame* to the queue and
        then returns without waiting for the frame to be sent.

        :param frame:
            Frame to be sent
        """

    @abc.abstractmethod
    async def send(self, frame: Frame):
        """Send frame to the remote peer.

        This method adds frame to the queue and then blocks until frame is
        removed from the queue and sent to underlying stream.

        :param frame:
            Frame to be sent
        """

    @abc.abstractmethod
    def get_write_buffer_size(self) -> int:
        """Return size of the write buffer in bytes.

        This is useful to determine how much data can be sent without blocking.
        """


@export
class ITransportConnector(IClosable):
    """Base class for client-side connection factories."""

    @abc.abstractmethod
    async def connect(self) -> ITransportConnection:
        """Connect with a remote peer and return new connection object."""


@export
class ITransportAcceptor(IClosable):
    """Base class for server-side transport layer connection factories."""

    @abc.abstractmethod
    async def accept(self) -> ITransportConnection:
        """Accept connection from remote peer and return as a new instance of
        :class:`ITransportConnection`.

        Will raise :exc:`ITransportAcceptor.AcceptorClosedError` if acceptor is
        closed during awaiting or """
